<?php require __DIR__.'/../includes/functions.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST'||!check_csrf()) die('Invalid request'); $json=$_POST['content_json']??''; $data=json_decode($json,true); if(!is_array($data)){ $_SESSION['flash']='Invalid JSON. Content not saved.'; } else { save_content($data); $_SESSION['flash']='Content saved.'; } header('Location: index.php#content'); ?>